-- PostgreSQL schema, independent of Cloudflare/D1.
CREATE TABLE "activity_logs" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"user_id" integer,
	"action" text NOT NULL,
	"resource" text NOT NULL,
	"ip" text NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "categories" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" text NOT NULL,
	"description" text,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "customers" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"phone" text NOT NULL,
	"address" text NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "employees" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"phone" text NOT NULL,
	"birthday" text,
	"address" text,
	"department" text DEFAULT 'Management' NOT NULL,
	"position" text NOT NULL,
	"join_date" text NOT NULL,
	"avatar" text,
	"status" text DEFAULT 'Active' NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "inventory" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"variant_id" integer NOT NULL,
	"quantity" integer DEFAULT 0 NOT NULL,
	"threshold" integer DEFAULT 10 NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	CONSTRAINT "nonnegative_stock" CHECK("inventory"."quantity">=0)
);

CREATE TABLE "inventory_transactions" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"variant_id" integer NOT NULL,
	"action" text NOT NULL,
	"quantity" integer NOT NULL,
	"employee_id" integer,
	"note" text DEFAULT '' NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "notification_reads" (
	"user_id" integer NOT NULL,
	"notification_id" integer NOT NULL,
	PRIMARY KEY("user_id", "notification_id")
);

CREATE TABLE "notifications" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"title" text NOT NULL,
	"message" text NOT NULL,
	"audience" text DEFAULT 'All' NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "order_items" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"order_id" integer NOT NULL,
	"variant_id" integer NOT NULL,
	"quantity" integer NOT NULL,
	"price" numeric(14,2) NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	CONSTRAINT "positive_order_quantity" CHECK("order_items"."quantity">0)
);

CREATE TABLE "orders" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"code" text NOT NULL,
	"customer_id" integer NOT NULL,
	"revision" integer DEFAULT 0 NOT NULL,
	"total" numeric(14,2) NOT NULL,
	"payment_method" text NOT NULL,
	"payment" text DEFAULT 'Unpaid' NOT NULL,
	"status" text DEFAULT 'Pending' NOT NULL,
	"created_by" integer NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	CONSTRAINT "positive_total" CHECK("orders"."total">=0)
);

CREATE TABLE "password_reset_tokens" (
	"token_hash" text PRIMARY KEY NOT NULL,
	"user_id" integer NOT NULL,
	"expires_at" bigint NOT NULL,
	"used" integer DEFAULT 0 NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "permissions" (
	"id" integer PRIMARY KEY NOT NULL,
	"name" text NOT NULL
);

CREATE TABLE "product_variants" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"product_id" integer NOT NULL,
	"sku" text NOT NULL,
	"size" text NOT NULL,
	"color" text NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "products" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" text NOT NULL,
	"sku" text NOT NULL,
	"description" text,
	"category_id" integer NOT NULL,
	"price" numeric(14,2) NOT NULL,
	"cost" numeric(14,2) NOT NULL,
	"supplier_id" integer NOT NULL,
	"image" text,
	"status" text DEFAULT 'Active' NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "rate_limits" (
	"key" text PRIMARY KEY NOT NULL,
	"count" integer NOT NULL,
	"rate_window" integer NOT NULL
);

CREATE TABLE "role_permissions" (
	"role_id" integer NOT NULL,
	"permission_id" integer NOT NULL,
	PRIMARY KEY("role_id", "permission_id")
);

CREATE TABLE "roles" (
	"id" integer PRIMARY KEY NOT NULL,
	"name" text NOT NULL
);

CREATE TABLE "sessions" (
	"token_hash" text PRIMARY KEY NOT NULL,
	"user_id" integer NOT NULL,
	"csrf" text NOT NULL,
	"expires_at" bigint NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "settings" (
	"key" text PRIMARY KEY NOT NULL,
	"value" text NOT NULL
);

CREATE TABLE "suppliers" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" text NOT NULL,
	"contact_person" text NOT NULL,
	"phone" text NOT NULL,
	"email" text NOT NULL,
	"address" text NOT NULL,
	"status" text DEFAULT 'Active' NOT NULL,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE "user_roles" (
	"user_id" integer NOT NULL,
	"role_id" integer NOT NULL,
	PRIMARY KEY("user_id", "role_id")
);

CREATE TABLE "users" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" text NOT NULL,
	"username" text NOT NULL,
	"email" text NOT NULL,
	"phone" text,
	"employee_id" integer,
	"status" text DEFAULT 'Active' NOT NULL,
	"avatar" text,
	"password_hash" text NOT NULL,
	"failed_attempts" integer DEFAULT 0 NOT NULL,
	"locked_until" bigint DEFAULT 0 NOT NULL,
	"last_login" timestamptz,
	"created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

ALTER TABLE "activity_logs" ADD CONSTRAINT "activity_logs_fk_1" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "inventory" ADD CONSTRAINT "inventory_fk_1" FOREIGN KEY ("variant_id") REFERENCES "product_variants"("id") ON UPDATE no action ON DELETE cascade;

ALTER TABLE "inventory_transactions" ADD CONSTRAINT "inventory_transactions_fk_1" FOREIGN KEY ("variant_id") REFERENCES "product_variants"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "inventory_transactions" ADD CONSTRAINT "inventory_transactions_fk_2" FOREIGN KEY ("employee_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "notification_reads" ADD CONSTRAINT "notification_reads_fk_1" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE cascade;

ALTER TABLE "notification_reads" ADD CONSTRAINT "notification_reads_fk_2" FOREIGN KEY ("notification_id") REFERENCES "notifications"("id") ON UPDATE no action ON DELETE cascade;

ALTER TABLE "order_items" ADD CONSTRAINT "order_items_fk_1" FOREIGN KEY ("order_id") REFERENCES "orders"("id") ON UPDATE no action ON DELETE cascade;

ALTER TABLE "order_items" ADD CONSTRAINT "order_items_fk_2" FOREIGN KEY ("variant_id") REFERENCES "product_variants"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "orders" ADD CONSTRAINT "orders_fk_1" FOREIGN KEY ("customer_id") REFERENCES "customers"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "orders" ADD CONSTRAINT "orders_fk_2" FOREIGN KEY ("created_by") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "password_reset_tokens" ADD CONSTRAINT "password_reset_tokens_fk_1" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "product_variants" ADD CONSTRAINT "product_variants_fk_1" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON UPDATE no action ON DELETE cascade;

ALTER TABLE "products" ADD CONSTRAINT "products_fk_1" FOREIGN KEY ("category_id") REFERENCES "categories"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "products" ADD CONSTRAINT "products_fk_2" FOREIGN KEY ("supplier_id") REFERENCES "suppliers"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "role_permissions" ADD CONSTRAINT "role_permissions_fk_1" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "role_permissions" ADD CONSTRAINT "role_permissions_fk_2" FOREIGN KEY ("permission_id") REFERENCES "permissions"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "sessions" ADD CONSTRAINT "sessions_fk_1" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE cascade;

ALTER TABLE "user_roles" ADD CONSTRAINT "user_roles_fk_1" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE cascade;

ALTER TABLE "user_roles" ADD CONSTRAINT "user_roles_fk_2" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON UPDATE no action ON DELETE no action;

ALTER TABLE "users" ADD CONSTRAINT "users_fk_1" FOREIGN KEY ("employee_id") REFERENCES "employees"("id") ON UPDATE no action ON DELETE no action;

CREATE INDEX "activity_time" ON "activity_logs" ("created_at");

CREATE UNIQUE INDEX "employees_email_unique" ON "employees" ("email");

CREATE UNIQUE INDEX "inventory_variant_id_unique" ON "inventory" ("variant_id");

CREATE INDEX "stock_history" ON "inventory_transactions" ("variant_id","created_at");

CREATE UNIQUE INDEX "orders_code_unique" ON "orders" ("code");

CREATE INDEX "order_date" ON "orders" ("created_at");

CREATE UNIQUE INDEX "permissions_name_unique" ON "permissions" ("name");

CREATE UNIQUE INDEX "product_variants_sku_unique" ON "product_variants" ("sku");

CREATE UNIQUE INDEX "variant_unique" ON "product_variants" ("product_id","size","color");

CREATE INDEX "variant_product" ON "product_variants" ("product_id");

CREATE UNIQUE INDEX "products_sku_unique" ON "products" ("sku");

CREATE UNIQUE INDEX "roles_name_unique" ON "roles" ("name");

CREATE INDEX "session_user" ON "sessions" ("user_id");

CREATE UNIQUE INDEX "users_username_unique" ON "users" ("username");

CREATE UNIQUE INDEX "users_email_unique" ON "users" ("email");
CREATE UNIQUE INDEX users_username_lower_unique ON users (lower(username));
CREATE UNIQUE INDEX users_email_lower_unique ON users (lower(email));
